{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Codeine, the closest structural analogue (Morgan 0.4058), has an absolute oral bioavailability of 42–71% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ethylmorphine, a close codeine analogue, showed a median minimum oral availability of 0.74 (range 0.54–0.92) in healthy subjects, supporting high oral bioavailability for this morphinan class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Morphine, sharing the same morphinan scaffold, has an absolute oral bioavailability of 32% in healthy volunteers, above the 20% threshold despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Noscapine, another opium alkaloid, has an absolute oral bioavailability of 30% (range 16–58%) in humans, reinforcing that morphinan alkaloids generally exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Morphine-6-glucuronide has poor oral bioavailability, but as a highly polar glucuronide conjugate it has low transferability to the lipophilic morphinan query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Cepharanthine has a low absolute oral bioavailability of 6–9%, but its large bisbenzylisoquinoline structure is distant from the query and has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a codeine-like morphinan alkaloid. The closest analogue codeine has absolute oral bioavailability of 42–71%, and other related morphinan/opioid analogues (ethylmorphine, morphine, noscapine, pethidine) all exceed 20%. Low-bioavailability evidence comes from structurally distant molecules (M6G glucuronide, cepharanthine) with low transferability. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule (neopine-like isomer).",
    "Most evidence does not specify fed/fasted conditions, while the query is assessed in the fasted state.",
    "Human pharmacokinetic data for neopine specifically are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

